import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import OrganizerDashboard from './features/dashboard/organizer/OrganizerDashboard';
import AttendeeDashboard from './features/dashboard/attendee/AttendeeDashboard';
import CreateEvent      from './features/dashboard/organizer/CreateEvent';
import MyEvents         from './features/dashboard/organizer/MyEvents';
import JoinSession from './features/dashboard/attendee/JoinSession';


function App() {
  return (
    <BrowserRouter>
      <Navbar />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/organizer/dashboard" element={<OrganizerDashboard />} />
        <Route path="/attendee/dashboard" element={<AttendeeDashboard />} />
        <Route path="/organizer/create-event" element={<CreateEvent />} />
        <Route path="/organizer/my-events"    element={<MyEvents    />} />
        <Route path="/join" element={<JoinSession />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
